import $ from "jquery";
// 15Apr2024 import Handlebars from "Handlebars";
import Handlebars, { W } from "handlebars/dist/handlebars"; // 15Apr2024
import bootstrap from "bootstrap/dist/js/bootstrap";
import * as d3 from "d3";
import HelperUtil from "./modules/helperutils";

function Geointerpreter() {
  const publicAPI = {};
  let mHelperUtil;
  let mMediator;

  publicAPI.setMediator = function (m) {
    mMediator = m;
  };
  publicAPI.getMediator = function () {
    return mMediator;
  };

  /**
   * Requests persistent storage for the application's data (including cached models).
   * This prevents the browser from automatically clearing the cache when storage is low.
   */
  async function requestPersistentStorage() {
    if (navigator.storage && navigator.storage.persist) {
      const isPersisted = await navigator.storage.persisted();
      console.log(`Storage is currently persisted: ${isPersisted}`);
      if (!isPersisted) {
        try {
          const wasPersisted = await navigator.storage.persist();
          if (wasPersisted) {
            console.log(
              "Successfully enabled persistent storage for the origin."
            );
          } else {
            console.warn(
              "Failed to enable persistent storage. The browser may clear data under storage pressure."
            );
          }
        } catch (error) {
          console.error("Error requesting persistent storage:", error);
        }
      }
    } else {
      console.warn("Persistent Storage API is not supported in this browser.");
    }
  }
  // Main function to run our analysis
  async function initializeApplication() {
    // --- Worker Setup ---
    // All heavy lifting (AI, DB) is moved to the worker.
    // The `import.meta.url` construct is the modern standard, but can fail in some
    // development environments or bundlers that don't support it correctly.
    // Using a direct path relative to the HTML file is a more robust fallback.
    // This assumes your HTML file is in the root directory and scripts are in a 'scripts' folder.
    const worker = new Worker('./scripts/geointerpreter-worker.js', { type: 'module' });

    const outputElement = document.getElementById("analysis-output");
    const userInputField = document.getElementById("user-input");
    const sendButton = document.getElementById("send-button");
    const cancelAnalysisButton = document.getElementById(
      "cancel-analysis-button"
    );
    const newSessionButton = document.getElementById("new-session-button");
    const chatHistoryDiv = document.getElementById("chat-history");
    const toggleThinkingButton = document.getElementById(
      "toggle-thinking-button"
    );
    const thinkingProcessContent = document.getElementById(
      "thinking-process-content"
    );
    const thinkingProcessWrapper = document.getElementById(
      "thinking-process-wrapper"
    );
    const chatInputContainer = document.getElementById("chat-input-container");
    // Get references to the new user prompt elements
    const userPromptContainer = document.getElementById(
      "user-prompt-container"
    );
    const userPromptQuestion = document.getElementById("user-prompt-question");
    const userPromptInput = document.getElementById("user-prompt-input");
    const userPromptSubmit = document.getElementById("user-prompt-submit");
    const userPromptOptions = document.getElementById("user-prompt-options");

    const typewriter = {
      queue: [],
      isTyping: false,
      speed: 10, // ms per character

      add(text) {
        // Add new text to the queue as individual characters
        // If this is the first text being added for a new thought, expand the UI.
        if (
          !this.isTyping &&
          thinkingProcessWrapper &&
          !thinkingProcessWrapper.classList.contains("show")
        ) {
          thinkingProcessCollapse.show();
        }

        this.queue.push(...text.split(""));
        // If not already typing, start
        if (!this.isTyping) {
          this.type();
        }
      },

      async type() {
        this.isTyping = true;
        while (this.queue.length > 0) {
          const char = this.queue.shift();
          thinkingProcessContent.textContent += char;

          // Fix: Scroll the thinking process content itself (it has the scrollbar)
          thinkingProcessContent.scrollTop =
            thinkingProcessContent.scrollHeight;

          await new Promise((resolve) => setTimeout(resolve, this.speed));
        }
        this.isTyping = false;
      },

      clear() {
        this.queue = [];
        thinkingProcessContent.textContent = "";
      },
    };

    // Initialize the Bootstrap Collapse instance once for efficiency.
    const thinkingProcessCollapse = new bootstrap.Collapse(
      thinkingProcessWrapper,
      {
        toggle: false,
      }
    );

    // Remove the manual event listener and let Bootstrap handle the toggle
    // toggleThinkingButton.addEventListener("click", () => {
    //   thinkingProcessCollapse.toggle();
    // });

    // Handle button text change on collapse toggle for the "Show Thinking" UI
    if (thinkingProcessWrapper && toggleThinkingButton) {
      thinkingProcessWrapper.addEventListener("show.bs.collapse", () => {
        toggleThinkingButton.innerHTML =
          'Hide Thinking <i class="bi bi-chevron-up toggle-icon"></i>';
      });

      thinkingProcessWrapper.addEventListener("hide.bs.collapse", () => {
        toggleThinkingButton.innerHTML =
          'Show Thinking <i class="bi bi-chevron-down toggle-icon"></i>';
      });
    }

    // Request persistent storage early in the lifecycle
    await requestPersistentStorage();

    const modelId = "Hermes-2-Pro-Llama-3-8B-q4f16_1-MLC"; // supports OpenAI's API for function calling

    // --- Worker Communication ---
    let lastThinkingProcess = "";

    worker.onmessage = (event) => {
      const { type, payload } = event.data;
      console.log(`Main thread received message: ${type}`, payload);

      switch (type) {
        case 'initProgress': {
          const { llmProgress, embeddingProgress } = payload;
          const llmMsg = `LLM (${modelId}): ${llmProgress.text} (${llmProgress.percentage}%)`;
          const embeddingMsg = `Embedding Model: ${embeddingProgress.text} (${embeddingProgress.percentage}%)`;
          outputElement.innerHTML = `Initializing AI systems...<br>${llmMsg}<br>${embeddingMsg}`;
          break;
        }

        case 'ready':
          outputElement.textContent = "AI systems ready. Ask a question.";
          userInputField.disabled = false;
          sendButton.disabled = false;
          break;

        case 'initError':
          console.error("Worker Initialization error:", payload);
          outputElement.textContent = `Error during initialization: ${payload.message || "An unknown error occurred."}`;
          break;

        case 'stateUpdate': {
          const state = payload;
          // Update UI based on state.agentStatus
          console.log("Agent Status:", state.agentStatus);

          if (cancelAnalysisButton) {
            cancelAnalysisButton.style.display = (state.agentStatus === "idle") ? "none" : "inline-block";
          }

          if (state.agentStatus === "idle") {
            outputElement.textContent = "Ready for your questions.";
            userInputField.disabled = false;
            sendButton.disabled = false;
            chatInputContainer.style.display = "flex";
            userPromptContainer.style.display = "none";
          } else {
            outputElement.textContent = `Agent Status: ${state.agentStatus.replace(/_/g, " ")}...`;
            userInputField.disabled = true;
            sendButton.disabled = true;
            if (state.agentStatus !== "waiting_for_user") {
              chatInputContainer.style.display = "flex";
            }
          }

          // Update conversation history in UI
          chatHistoryDiv.innerHTML = ""; // Clear and re-render
          state.conversationHistory.forEach((message) => {
            const role = message.role === "user" ? "You" : "GeoInterpreter";
            const messageClass = message.role === "tool" ? "tool-message" : `${message.role}-message`;
            const content = message.content || "";
            chatHistoryDiv.innerHTML += `<div class="message-container"><div class="${messageClass}"><strong>${role}:</strong> ${content.replace(/\n/g, "<br>")}</div></div>`;
          });
          chatHistoryDiv.scrollTop = chatHistoryDiv.scrollHeight;
          break;
        }

        case 'aiThinkingStream': {
          const newThinkingProcess = payload.content;
          if (newThinkingProcess === "") {
            typewriter.clear();
            lastThinkingProcess = "";
            return;
          }
          const diff = newThinkingProcess.substring(lastThinkingProcess.length);
          if (diff) {
            typewriter.add(diff);
          }
          lastThinkingProcess = newThinkingProcess;
          break;
        }

        case 'finalAnswerReady':
          outputElement.textContent = "Analysis complete.";
          break;

        case 'promptUserForInput': {
          const { question, options } = payload;
          chatInputContainer.style.display = "none";
          userPromptContainer.style.display = "block";
          userPromptQuestion.textContent = question;
          userPromptOptions.innerHTML = "";
          userPromptInput.value = "";

          if (options && options.length > 0) {
            userPromptInput.parentElement.style.display = "none";
            options.forEach((optionText) => {
              const button = document.createElement("button");
              button.textContent = optionText;
              button.className = "btn btn-outline-primary me-2 mb-2";
              button.addEventListener("click", () => {
                worker.postMessage({ type: 'userInputProvided', payload: { response: optionText } });
                userPromptContainer.style.display = "none";
              });
              userPromptOptions.appendChild(button);
            });
          } else {
            userPromptInput.parentElement.style.display = "block";
            userPromptInput.focus();
          }
          break;
        }

        case 'userQuerySubmitted': {
          // When a new query starts, clear the thinking process UI and the state
          typewriter.clear();
          lastThinkingProcess = "";
          break;
        }
      }
    };

    // --- Event Listeners to send messages TO the worker ---
    sendButton.addEventListener("click", () => {
      const userQueryText = userInputField.value.trim();
      if (userQueryText) {
        userInputField.value = "";
        worker.postMessage({ type: 'userQuery', payload: { query: userQueryText } });
      }
    });

    userInputField.addEventListener("keypress", (event) => {
      if (event.key === "Enter") {
        sendButton.click();
      }
    });

    if (cancelAnalysisButton) {
      cancelAnalysisButton.addEventListener("click", () => {
        worker.postMessage({ type: 'cancelProcessing' });
      });
    }

    if (newSessionButton) {
      newSessionButton.addEventListener("click", () => {
        worker.postMessage({ type: 'newSessionRequested' });
      });
    }

    const submitUserResponse = () => {
      const response = userPromptInput.value.trim();
      if (response) {
        worker.postMessage({ type: 'userInputProvided', payload: { response } });
        userPromptContainer.style.display = "none";
      }
    };

    userPromptSubmit.addEventListener("click", submitUserResponse);
    userPromptInput.addEventListener("keypress", (event) => {
      if (event.key === "Enter") submitUserResponse();
    });

    // --- Start Initialization ---
    // Send the first message to the worker to kick off initialization.
    worker.postMessage({ type: 'initialize' });

    // The old try/catch block is removed from here as initialization
    // now happens in the worker, and errors are handled via messages.
  }

  publicAPI.init = function () {
    mHelperUtil = new HelperUtil();
    // Check if DOM is already loaded
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initializeApplication);
    } else {
      // DOM is already loaded, call function directly
      console.log("DOM already loaded, initializing application directly");
      initializeApplication();
    }

    // For debugging purposes
    console.log("Geointerpreter.init() called");
  };

  return publicAPI;
}
export default Geointerpreter;